using ConjuntoInteligente.PbBridge.Contracts; using ConjuntoInteligente.PbBridge.Contracts.Dtos; using ConjuntoInteligente.PbBridge.Services; using Microsoft.AspNetCore.Mvc;
namespace ConjuntoInteligente.PbBridge.Controllers;
[Route("pb/v1/vendors")] public sealed class PbVendorsController:PbBaseController{private readonly ICoreClient _core;private readonly IPbMapper _mapper;public PbVendorsController(ICoreClient core,IPbMapper mapper){_core=core;_mapper=mapper;}
 [HttpGet("{id}")] public async Task<IActionResult> Get(string id,CancellationToken ct){var vendor=await _core.GetAsync<CoreVendor>($"api/v1/maintenance/vendors/{Uri.EscapeDataString(id)}",ct);return vendor is null?PbFail(PbErrorCodes.NotFound,"Proveedor no encontrado.",404):PbOk(_mapper.ToPb(vendor));}
 [HttpPost] public async Task<IActionResult> Create([FromBody]PbVendorRequest request,CancellationToken ct){var result=await _core.PostAsync<CoreMaintenanceMutation>("api/v1/maintenance/vendors",request,ct);return result is null?PbFail(PbErrorCodes.CoreError,"El core no devolvió el resultado de creación.",502):StatusCode(201,PbResponse<CoreMaintenanceMutation>.Success(result));}
 [HttpPut("{id}")] public async Task<IActionResult> Update(string id,[FromBody]PbVendorRequest request,CancellationToken ct){var result=await _core.PutAsync<CoreMaintenanceMutation>($"api/v1/maintenance/vendors/{Uri.EscapeDataString(id)}",request,ct);return result is null?PbFail(PbErrorCodes.NotFound,"Proveedor no encontrado.",404):PbOk(result);}
 [HttpGet("list")] public async Task<IActionResult> List([FromQuery]string? categoria,[FromQuery]string? estado,CancellationToken ct=default){var qs=new List<string>{"page=1","page_size=200"};if(!string.IsNullOrWhiteSpace(categoria))qs.Add($"category={Uri.EscapeDataString(categoria!)}");if(!string.IsNullOrWhiteSpace(estado))qs.Add($"status={Uri.EscapeDataString(estado!)}");var page=await _core.GetAsync<CoreVendorPage>($"api/v1/maintenance/vendors?{string.Join('&',qs)}",ct);return PbOk(page is null?Array.Empty<PbVendorDto>():page.Items.Select(_mapper.ToPb).ToArray());}}
public sealed record CoreVendorPage(IReadOnlyList<CoreVendor> Items,int Total);
